void hazard_status_update( Boolean instant_status )
{
	
	if(hazard_was_instantiated)
    {    
		static Boolean last_status = FALSE ;
        
        if( instant_status && !last_status )
        {
            os_evt_signal( hazard_evt , HAZARD_EVT_STATUS_ON );
        }
        
        if( !instant_status && last_status )
        {
            os_evt_signal( hazard_evt , HAZARD_EVT_STATUS_OFF );
        }
        
        last_status = instant_status ;        
    }
}

